import { createPresenceChannel } from "./channel.js";
import { subscribeChannel } from "./subscription.js";

export function createPresencePanel(publish) {
  let currentVisit = null;

  const retireCurrentVisit = () => {
    const visit = currentVisit;
    currentVisit = null;
    if (visit && visit.release) visit.release();
  };

  return {
    show(channel, bootstrapMode = "synchronous") {
      retireCurrentVisit();

      const visit = { release: null };
      currentVisit = visit;
      let release;
      try {
        release = subscribeChannel(channel, bootstrapMode, (value) => {
          if (currentVisit === visit) publish(value);
        });
      } catch (error) {
        if (currentVisit === visit) currentVisit = null;
        throw error;
      }

      if (currentVisit === visit) visit.release = release;
      else release();
    },
    close() {
      retireCurrentVisit();
    },
  };
}

export async function renderPresence(token, bootstrapMode) {
  const events = [];
  const panel = createPresencePanel((value) => events.push(value));
  const channel = createPresenceChannel(token);
  panel.show(channel, bootstrapMode);
  await Promise.resolve();
  channel.emitUpdate();
  panel.close();
  return { events };
}

